    'anchor'=>'',
    'anchorOffset'=>'0',
    'label',  
    'cursor'=>'cursor-pointer',
    'tag'=>'a',
    'target'=>'_self',
    'link'=>'',
    'block'=>false,
    'big'=>false,
    'small'=>false,
    'disabled'=>false,
    'class'=>'', 
    'icon'=>'',
    'iconPosition'=>'left', 
    'btnNoTxt_mobile'=>false,
    'submit' => false,
    'id'=> false,
])
<{{$tag}} class="
    @if(!empty($anchor)) anchor @endif 
    @if($disabled) c-btnDisabled cursor-not-allowed @else cursor-pointer @endif
    rounded border border-black/20 font-mono uppercase text-2xs @if(empty($icon)) text-center @else text-left @endif
    @if($block) block @else inline-block @endif 
    @if($big) min-h-12 px-4 py-2 @elseif($small) min-h-4 px-3 py-1.5 @else min-h-9 px-3 py-2.5 @endif 
    transition-all hover:bg-black/10 hover:border-white duration-700 
    {{$class}}"

    @if(!empty($link)) href="{{$link}}" target="{{$target}}" @endif 
    data-anchor-offset="{{$anchorOffset}}"
    @if($submit) type="submit" @endif

    @if($id) id="{{$id}}" @endif
    >
    @if(empty($icon)) 
        {{$label}}
    @else
        {{-- se c'è l'icona --}}
        <span class="flex gap-2 items-center">
            <span class="c-txt flex-1 order-2 @if($btnNoTxt_mobile) hidden sm:inline-block @endif">
                {{$label}}
            </span>

            {{-- ICONA --}}
            <img src="/img/icons/{{$icon}}" alt="{{$label}}" class="@if($iconPosition === 'left') order-1 @else order-3 @endif mx-1" width="12" height="12">
        </span>

    @endif
</{{$tag}}>

